  while (SNOWF.length < want) SNOWF.push({ x: Math.random() * vw, y: Math.random() * vh, z: 0.3 + Math.random() * 0.7, ph: Math.random() * 6.28 });
  if (SNOWF.length > want) SNOWF.length = want;
