    if (mins < 10) { if (mins >= 3) tell(`꺼져 있던 시간이 ${fmt(mins)}이라 정산하지 않았어요. (10분 이상부터)`); return; }
    const R = (Array.isArray(o.rec) ? o.rec : []).filter(Array.isArray).slice(-MAXM), M = R.length;
