    const rk = id => ({ 일반: 0, 고급: 1, 희귀: 2, 영웅: 3 })[(ITEMS[id] && ITEMS[id].rar) || '일반'] || 0;
    const items = Object.entries(res.got).sort((a, b) => rk(b[0]) - rk(a[0]) || b[1] - a[1]), cnt = items.reduce((a, x) => a + x[1], 0);
